import { PERIODICITY } from '@/modules/chargeConcept/schema'

/** Forma mínima evaluada por isAutoGenerated — la cumple cualquier política/concepto con periodicidad. */
export interface AutoGeneratable {
  is_active?: boolean
  periodicity?: { is_automatic?: boolean } | null
}

/**
 * Una entidad cuya periodicidad es automática (is_automatic) y está activa genera
 * cargos por cron. Tras el split concepto→política, aplica a la POLÍTICA (que es la
 * que lleva periodicidad/vigencia).
 *
 * ADR-6: reads periodicity.is_automatic (boolean from backend) instead of comparing
 * periodicity_id to a hardcoded UUID — eliminates brittle UUID coupling.
 */
export function isAutoGenerated(entity: AutoGeneratable): boolean {
  return entity.periodicity?.is_automatic === true && entity.is_active === true
}

/**
 * Etiqueta de cadencia legible según la periodicidad.
 * Usada en el badge "Automático · genera {cadencia}" de ChargeConceptListPage.
 */
export function periodicityCadenceLabel(periodicityId?: string | null): string {
  switch (periodicityId) {
    case PERIODICITY.MONTHLY:
      return 'cada mes'
    case PERIODICITY.BIMONTHLY:
      return 'cada 2 meses'
    case PERIODICITY.YEARLY:
      return 'cada año'
    case PERIODICITY.WEEKLY:
      return 'cada semana'
    case PERIODICITY.BIWEEKLY:
      return 'cada quincena'
    case PERIODICITY.EVERY_TWO_DAYS:
      return 'cada 2 días (pruebas)'
    case PERIODICITY.EVENTUAL:
      return 'a demanda (eventual)'
    default:
      return 'automáticamente'
  }
}
